    charset: Vec<u8>,
    // Direct lookup table: byte value -> index in charset (avoids HashMap hashing)
    charset_lookup: [u8; 128],
    charset_len: usize,
    charset_last_idx: u8,
    max_size: usize,
    generated_count: usize,
    total_to_generate: usize,
    password: Vec<u8>,
    progress_bar: ProgressBar,
