                        charset,
                        min_password_len,
                        max_password_len,
                        starting_password,
                        pb,
                    ))
                }
                Strategy::PasswordFile(dictionary_path) => Either::Right(Either::Left(
                    password_dictionary_reader_iter(dictionary_path),
                )),
                Strategy::MaskGenPasswords { mask } => {
                    Either::Right(Either::Right(mask_password_iter(mask)))
                }
            };
